import React from 'react';
import { Menu, MenuItem } from '@mui/material';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';

export default function LeadChatComposerAttachMenu({
  anchorEl,
  open,
  onClose,
  canSendTemplate = false,
  canAttachMedia = true,
  onPickTemplate,
  onPickImage,
  onPickVideo,
  onPickDocument,
}) {
  const pick = (handler) => () => {
    onClose?.();
    handler?.();
  };

  return (
    <Menu anchorEl={anchorEl} open={open} onClose={onClose}>
      {canSendTemplate ? (
        <MenuItem onClick={pick(onPickTemplate)}>
          {LEAD_CHAT_COPY.composer.template}
        </MenuItem>
      ) : null}
      <MenuItem disabled={!canAttachMedia} onClick={pick(onPickImage)}>
        {LEAD_CHAT_COPY.composer.image}
      </MenuItem>
      <MenuItem disabled={!canAttachMedia} onClick={pick(onPickVideo)}>
        {LEAD_CHAT_COPY.composer.video}
      </MenuItem>
      <MenuItem disabled={!canAttachMedia} onClick={pick(onPickDocument)}>
        {LEAD_CHAT_COPY.composer.document}
      </MenuItem>
    </Menu>
  );
}
