import { canStartLeadChatSession, isLeadChatSessionActive } from './leadChatSessionRules';
import { getLastActiveFromUser, isSessionExpired } from './leadChatSessionWindow';

/** @typedef {'active' | 'idle' | 'expired'} LeadChatComposerMode */

export function getLeadChatComposerMode(user) {
  const lastActive = getLastActiveFromUser(user);
  if (lastActive && isSessionExpired(lastActive)) return 'expired';
  if (isLeadChatSessionActive(user)) return 'active';
  if (canStartLeadChatSession(user)) return 'idle';
  return 'active';
}

export function isComposerExpired(mode) {
  return mode === 'expired';
}

export function isComposerIdle(mode) {
  return mode === 'idle';
}

export function canComposeFreeForm(mode) {
  return mode === 'active';
}
