import React, { useMemo } from 'react';
import { Box, CircularProgress, Typography } from '@mui/material';
import { DataTable, EmptyState, TableSkeleton } from '../../../../../../components/ui';
import { useFeatureTheme } from '../../../../../../theme/hooks/useFeatureTheme';
import useBusinessFunctionsTableSx from '../../../../hooks/useBusinessFunctionsTableSx';
import { buildTemplateUsersTableColumns } from '../../../config/statusLogTableColumns';
import { RECORD_COPY } from '../../../constants/recordCopy';

export default function StatusLogTemplateUsersTable({
  rows = [],
  loading = false,
  selectedDate = '',
  isMobile = false,
}) {
  const { semantic, typography } = useFeatureTheme();
  const { tableOverrides } = useBusinessFunctionsTableSx();
  const copy = RECORD_COPY.statusLogs.template;
  const columns = useMemo(() => buildTemplateUsersTableColumns(), []);
  const tableMaxHeight = isMobile ? 'calc(100dvh - 320px)' : 'min(52vh, 460px)';

  if (!selectedDate) {
    return (
      <EmptyState
        title={RECORD_COPY.statusLogs.selectDateFirst}
        description=""
        sx={{ py: { xs: 4, sm: 6 } }}
      />
    );
  }

  if (loading) {
    return (
      <Box sx={{ minHeight: 240, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
        <CircularProgress size={24} />
        <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}>
          {copy.loadingUsers}
        </Typography>
      </Box>
    );
  }

  if (!rows.length) {
    return <EmptyState title={copy.noUsers} description="" sx={{ py: { xs: 4, sm: 6 } }} />;
  }

  return (
    <Box
      sx={{
        border: `1px solid ${semantic.borders.border}`,
        borderRadius: 2,
        overflow: 'hidden',
        minWidth: 0,
      }}
    >
      <DataTable
        columns={columns}
        data={rows}
        getRowId={(row, index) => String(row.id || row.user_id || row.phone_number || index)}
        enableStickyHeader
        layoutMode="grid"
        skeleton={<TableSkeleton rowCount={6} columnCount={columns.length} />}
        muiTableHeadCellProps={tableOverrides.muiTableHeadCellProps}
        muiTableBodyCellProps={tableOverrides.muiTableBodyCellProps}
        muiTableContainerProps={{
          sx: {
            maxHeight: tableMaxHeight,
            overflowX: 'auto',
            overflowY: 'auto',
            WebkitOverflowScrolling: 'touch',
          },
        }}
      />
    </Box>
  );
}
