import React from 'react';
import { Box, Typography } from '@mui/material';
import useLeadChatSx from '../../hooks/useLeadChatSx';

export default function MediaMessage({ message }) {
  const sx = useLeadChatSx();
  const media = message.media || {};
  const kind = media.kind || message.kind || 'image';
  const url = media.url || message.mediaUrl;
  const caption = media.caption || message.text;

  if (!url && !caption) {
    return (
      <Typography variant="body2" sx={{ fontStyle: 'italic', opacity: 0.8 }}>
        Media unavailable
      </Typography>
    );
  }

  return (
    <Box sx={{ maxWidth: 240, width: '100%' }}>
      {url && kind === 'video' ? (
        <Box component="video" controls src={url} sx={sx.mediaVideo} />
      ) : null}
      {url && kind === 'audio' ? (
        <Box component="audio" controls src={url} sx={{ width: '100%', minWidth: 160 }} />
      ) : null}
      {url && kind !== 'video' && kind !== 'audio' ? (
        <Box
          component="a"
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          sx={{ display: 'block' }}
        >
          <Box component="img" src={url} alt="Shared media" sx={sx.mediaImage} />
        </Box>
      ) : null}
      {caption ? (
        <Typography variant="body2" sx={{ mt: url ? 0.75 : 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
          {caption}
        </Typography>
      ) : null}
    </Box>
  );
}
