import React from 'react';
import { Box, Divider, Tab, Tabs, Typography } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { Button } from '../../../../../../components/ui';
import { useFeatureTheme } from '../../../../../../theme/hooks/useFeatureTheme';
import { RECORD_COPY } from '../../../constants/recordCopy';
import StatusLogTemplateDetailsTab from './StatusLogTemplateDetailsTab';
import StatusLogTemplateDatesTable from './StatusLogTemplateDatesTable';
import StatusLogTemplateUsersTable from './StatusLogTemplateUsersTable';

export default function StatusLogTemplatePanel({
  selectedTemplate,
  templateTab,
  templateDateSummary = [],
  templateUsers = [],
  templateUsersTotal = 0,
  selectedTemplateDate = '',
  templateStartDate = '',
  templateEndDate = '',
  isTemplateLoading = false,
  isUsersLoading = false,
  templateDetailKeys = [],
  statusRows = [],
  isMobile = false,
  onBack,
  onTabChange,
  onDateClick,
  onStartDateChange,
  onEndDateChange,
  onClearRange,
}) {
  const { semantic, typography } = useFeatureTheme();
  const copy = RECORD_COPY.statusLogs;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <Box
        sx={{
          display: 'flex',
          alignItems: { xs: 'flex-start', sm: 'center' },
          flexDirection: { xs: 'column', sm: 'row' },
          gap: 1,
          mb: 1.5,
        }}
      >
        <Button
          variant="secondary"
          size="sm"
          icon={<ArrowBackIcon />}
          onClick={onBack}
          sx={{ width: { xs: '100%', sm: 'auto' } }}
        >
          {copy.backToLogs}
        </Button>
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            color: semantic.text.secondary,
            minWidth: 0,
            wordBreak: 'break-word',
          }}
        >
          {selectedTemplate?.name}
        </Typography>
      </Box>

      <Tabs
        value={templateTab}
        onChange={(_event, value) => onTabChange?.(value)}
        variant="scrollable"
        scrollButtons="auto"
        allowScrollButtonsMobile
        sx={{
          minHeight: 44,
          mb: 0.5,
          borderBottom: `1px solid ${semantic.borders.border}`,
          '& .MuiTab-root': {
            minHeight: 44,
            fontSize: typography.fontSizeSm,
            textTransform: 'none',
            fontWeight: typography.fontWeightMedium,
          },
        }}
      >
        <Tab value="details" label={copy.template.tabs.details} />
        <Tab
          value="dates"
          label={`${copy.template.tabs.dates} (${templateDateSummary.length})`}
        />
        <Tab
          value="users"
          label={`${copy.template.tabs.users} (${templateUsersTotal})`}
        />
      </Tabs>

      <Divider sx={{ mb: 2, display: 'none' }} />

      <Box sx={{ minHeight: 0, flex: 1 }}>
        {templateTab === 'details' ? (
          <StatusLogTemplateDetailsTab
            selectedTemplate={selectedTemplate}
            templateDetailKeys={templateDetailKeys}
            statusRows={statusRows}
            isMobile={isMobile}
          />
        ) : null}

        {templateTab === 'dates' ? (
          <StatusLogTemplateDatesTable
            rows={templateDateSummary}
            loading={isTemplateLoading}
            startDate={templateStartDate}
            endDate={templateEndDate}
            isMobile={isMobile}
            onStartDateChange={onStartDateChange}
            onEndDateChange={onEndDateChange}
            onClearRange={onClearRange}
            onDateClick={onDateClick}
          />
        ) : null}

        {templateTab === 'users' ? (
          <StatusLogTemplateUsersTable
            rows={templateUsers}
            loading={isUsersLoading}
            selectedDate={selectedTemplateDate}
            isMobile={isMobile}
          />
        ) : null}
      </Box>
    </Box>
  );
}
